import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; int n = Integer.parseInt(line.trim()); PrintWriter out = new PrintWriter(System.out); while (n-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int[] arr = new int[3]; arr[0] = Integer.parseInt(st.nextToken()); arr[1] = Integer.parseInt(st.nextToken()); arr[2] = Integer.parseInt(st.nextToken()); Arrays.sort(arr); out.println(arr[1]); } out.flush(); out.close(); } }